CREATE OR REPLACE FUNCTION public.ai_member_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.profiles WHERE user_id=auth.uid() AND suspended=true) $$;
REVOKE ALL ON FUNCTION public.ai_member_active() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.ai_member_active() TO authenticated, service_role;
CREATE TABLE public.ai_conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'محادثة جديدة', messages jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ai_conversations TO authenticated;
GRANT ALL ON public.ai_conversations TO service_role;
ALTER TABLE public.ai_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members own AI conversations" ON public.ai_conversations FOR ALL TO authenticated USING (user_id=auth.uid() AND public.ai_member_active()) WITH CHECK (user_id=auth.uid() AND public.ai_member_active());
CREATE INDEX ai_conversations_owner ON public.ai_conversations(user_id,updated_at DESC);
CREATE TABLE public.ai_library_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, path text NOT NULL UNIQUE, size bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.ai_library_files TO authenticated;
GRANT ALL ON public.ai_library_files TO service_role;
ALTER TABLE public.ai_library_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Members own AI files" ON public.ai_library_files FOR ALL TO authenticated USING (user_id=auth.uid() AND public.ai_member_active()) WITH CHECK (user_id=auth.uid() AND split_part(path,'/',1)=auth.uid()::text AND public.ai_member_active());
CREATE POLICY "AI private storage read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='ai-library' AND (storage.foldername(name))[1]=auth.uid()::text AND public.ai_member_active());
CREATE POLICY "AI private storage insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='ai-library' AND (storage.foldername(name))[1]=auth.uid()::text AND public.ai_member_active());
CREATE POLICY "AI private storage delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='ai-library' AND (storage.foldername(name))[1]=auth.uid()::text AND public.ai_member_active());
CREATE TABLE public.ai_contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, message text NOT NULL, sender_hash text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.ai_contact_messages TO authenticated;
GRANT ALL ON public.ai_contact_messages TO service_role;
ALTER TABLE public.ai_contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage AI inbox" ON public.ai_contact_messages FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX ai_contact_sender_time ON public.ai_contact_messages(sender_hash,created_at);
CREATE OR REPLACE FUNCTION public.submit_ai_contact(_name text,_email text,_message text,_sender_hash text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(_sender_hash,0));
IF (SELECT count(*) FROM public.ai_contact_messages WHERE sender_hash=_sender_hash AND created_at > now()-interval '10 minutes') >= 5 THEN RAISE EXCEPTION 'CONTACT_RATE_LIMIT'; END IF;
INSERT INTO public.ai_contact_messages(name,email,message,sender_hash) VALUES (_name,_email,_message,_sender_hash);
END $$;
REVOKE ALL ON FUNCTION public.submit_ai_contact(text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.submit_ai_contact(text,text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.protect_profile_suspension() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.suspended IS DISTINCT FROM OLD.suspended AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_suspension BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_suspension();